package top.ghhccghk.accompanist.folia.sample

import top.ghhccghk.accompanist.folia.sample.importing.loadSongContent
import top.ghhccghk.accompanist.folia.sample.playback.*
import kotlinx.coroutines.*
import java.io.File

/** Explicit hardware probe. Real, independently tagged files are generated by verification script. */
object EmbeddedAudioProbe {
    @JvmStatic fun main(args: Array<String>) = runBlocking {
        require(args.size == 2) { "Arguments: generated fixture directory, evidence output" }
        val directory = File(args[0])
        val output = File(args[1]).apply { parentFile.mkdirs() }
        val files = directory.listFiles()!!.filter { it.extension in setOf("mp3", "flac", "m4a", "wav") }.sortedBy { it.name }
        check(files.size == 6) { "Expected six independently tagged real audio files" }
        val records = mutableListOf("Sample production source/tag/parser path; files generated with FFmpeg and Mutagen, no user audio")
        for (file in files) {
            val content = loadSongContent(SongFiles(DesktopSongFile(file)))
            check(content.lyrics != null) { "${file.name}: ${content.notice}" }
            check(content.lyrics.lines.map { it.start } == listOf(1000, 3000)) { "${file.name}: timestamps differ" }
            check(content.notice == null) { "${file.name}: ${content.notice}" }
            records += "${file.name}: timed tags parsed; starts=1000,3000"
        }
        // WAV is within the sample's actual Desktop decoding contract. Other containers above test
        // tag reading only; they do not expand Java Sound's supported playback formats.
        val source = DesktopSongFile(File(directory, "timed.wav"))
        val songs = SongSession()
        try {
            check(songs.openContent(SongFiles(source), ::prepareDesktopAudio, ::loadSongContent)) { songs.error ?: "open failed" }
            delay(500); songs.poll()
            check(songs.snapshot.isPlaying && songs.snapshot.positionMillis in 100..2000)
            records += "real tagged WAV device cursor=${songs.snapshot.positionMillis}ms"
            songs.control { it.pause(); it.seek(1500) }; val paused = songs.snapshot
            delay(200); songs.poll(); check(songs.snapshot == paused)
            records += "paused seek=1500ms stable; same player snapshot drives lyrics"
            check(songs.current!!.lyrics!!.lines.first().start == 1000)
        } finally {
            songs.close()
            records += "session closed; Clip released"
            output.writeText(records.joinToString("\n") + "\n")
        }
        println("EMBEDDED_AUDIO_VERIFIED ${output.absolutePath}")
    }
}
